import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../../core/routing/app_router.dart';import '../../../models/incident.dart';import '../../../providers/auth_provider.dart';import '../../../repositories/incident_repository.dart';import '../../../services/firestore_service.dart';import '../../../services/storage_service.dart';import '../../../shared/widgets/empty_state.dart';import '../../../shared/widgets/loading_indicator.dart';import '../widgets/incident_card.dart';class MyIncidentsScreen extends StatelessWidget{const MyIncidentsScreen({super.key});@override Widget build(BuildContext context){final u=context.watch<AuthProvider>().firebaseUser;if(u==null)return const Scaffold(body:Center(child:Text('Please sign in.')));final repo=IncidentRepository(FirestoreService(),StorageService());return Scaffold(appBar:AppBar(title:const Text('My reports')),body:StreamBuilder<List<Incident>>(stream:repo.watchMine(u.uid),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const LoadingIndicator();if(s.hasError)return Center(child:Text('Could not load: ${s.error}'));final list=s.data??[];if(list.isEmpty)return const EmptyState(title:'No reports yet',message:'Incidents you submit will appear here.');return ListView.builder(itemCount:list.length,itemBuilder:(context,i)=>IncidentCard(incident:list[i],onTap:()=>Navigator.pushNamed(context,AppRouter.incidentDetails,arguments:list[i].id)));}));}}
